import React from 'react';
import {AbsoluteFill} from 'remotion';
import {useS, en, Camara, Subtitulos, Textura, Profundidad, Brillo, Paso, Recorrido, seguir, tono, Chip, Regla, Contador, Ondas, golpe, h, clamp, interpolate, Easing, FONT, MANO} from './kit';

export const SUBS = {arriba: 230, acento: '#E7FF00'};

// ---- tiempos atados a la voz ----
const Y1967 = en('1967'), HOMBRE = en('Hombrecitos'), JOC = en('Jocelyn'), VEINTI = en('veinticuatro'), SU = en('Su');
const KM = en('kilómetros'), RADIO = en('radiotelescopio'), UN = en('Un', 2), MANCH = en('manchita'), CADA = en('cada'), RELOJ = en('reloj');
const NADA = en('Nada', 2), BROMA = en('broma'), SEMANAS = en('Semanas'), OTRA = en('otra'), EXTRA = en('extraterrestres'), NO2 = en('no', 2);
const ESTRELLA = en('estrella'), CIUDAD = en('ciudad'), HABIA = en('Había'), PULSARES = en('púlsares'), Y1974 = en('1974'), NOBEL = en('Nobel');
const DIERON = en('dieron'), ELLA = en('ella'), CUARENTA = en('Cuarenta'), PREMIO2 = en('premio', 2), DOLARES = en('dólares'), DONO = en('donó');
const ESTUD = en('estudiantes'), MANCH2 = en('manchita', 2), LLEVA = en('lleva'), CREDITO = en('crédito');

const LIMA = '#E7FF00', CREMA = '#F2E8CF', NOCHE = '#0E1A3A', ORO = '#C9B26B';

const Lienzo: React.FC<{children: React.ReactNode}> = ({children}) => <svg width={1080} height={1920} style={{position: 'absolute', inset: 0}}>{children}</svg>;

const corta = (P: [number, number][], D: number) => {
  const out: [number, number][] = [P[0]];
  let rest = D;
  for (let i = 1; i < P.length; i++) {
    const L = Math.hypot(P[i][0] - P[i - 1][0], P[i][1] - P[i - 1][1]);
    if (rest >= L) { out.push(P[i]); rest -= L; } else {
      const k = rest / L;
      out.push([P[i - 1][0] + (P[i][0] - P[i - 1][0]) * k, P[i - 1][1] + (P[i][1] - P[i - 1][1]) * k]);
      break;
    }
  }
  return out;
};

// extraterrestre de caricatura (solo cabeza), guiña o se ríe
const Alien: React.FC<{x: number; y: number; sc?: number; guino?: number; risa?: boolean; rot?: number}> = ({x, y, sc = 1, guino = 0, risa = false, rot = 0}) => (
  <g transform={`translate(${x} ${y}) rotate(${rot}) scale(${sc})`}>
    <ellipse cx={0} cy={95} rx={95} ry={16} fill="rgba(0,0,0,0.3)" />
    <line x1={-34} y1={-70} x2={-62} y2={-135} stroke="#2E7D32" strokeWidth={8} strokeLinecap="round" />
    <line x1={34} y1={-70} x2={62} y2={-135} stroke="#2E7D32" strokeWidth={8} strokeLinecap="round" />
    <circle cx={-62} cy={-140} r={13} fill={LIMA} stroke="#2E7D32" strokeWidth={4} />
    <circle cx={62} cy={-140} r={13} fill={LIMA} stroke="#2E7D32" strokeWidth={4} />
    <ellipse cx={0} cy={0} rx={78} ry={92} fill="#7BE070" stroke="#2E7D32" strokeWidth={6} />
    <ellipse cx={-26} cy={-34} rx={18} ry={30} fill="#C8F5A8" opacity={0.6} />
    <ellipse cx={-30} cy={-6} rx={24} ry={30} fill="#fff" stroke="#2E7D32" strokeWidth={4} />
    {guino > 0.5 ? <path d="M 8 -6 Q 32 -20 56 -6" stroke="#102510" strokeWidth={7} fill="none" strokeLinecap="round" /> : <><ellipse cx={32} cy={-6} rx={24} ry={30} fill="#fff" stroke="#2E7D32" strokeWidth={4} /><circle cx={36} cy={-4} r={11} fill="#102510" /></>}
    <circle cx={-26} cy={-4} r={11} fill="#102510" />
    {risa ? <path d="M -40 42 Q 0 100 40 42 Z" fill="#2a1030" stroke="#102510" strokeWidth={5} /> : <path d="M -34 46 Q 0 72 34 46" stroke="#102510" strokeWidth={6} fill="none" strokeLinecap="round" />}
  </g>
);

// busto de persona
const Figura: React.FC<{x: number; y: number; sc?: number; pelo: string; ropa: string; piel?: string; rot?: number; corbata?: string; op?: number}> = ({x, y, sc = 1, pelo, ropa, piel = '#E8B894', rot = 0, corbata, op = 1}) => (
  <g transform={`translate(${x} ${y}) rotate(${rot}) scale(${sc})`} opacity={op}>
    <path d="M -120 220 C -120 90 -80 48 0 48 C 80 48 120 90 120 220 Z" fill={ropa} stroke="rgba(0,0,0,0.4)" strokeWidth={5} />
    {corbata && <path d="M -14 50 L 14 50 L 20 150 L 0 170 L -20 150 Z" fill={corbata} />}
    {corbata && <path d="M -40 50 L 0 100 L 40 50 L 14 48 L 0 70 L -14 48 Z" fill="#F4F4F4" />}
    <rect x={-20} y={8} width={40} height={50} rx={14} fill={piel} />
    <ellipse cx={0} cy={-34} rx={58} ry={68} fill={piel} stroke="rgba(0,0,0,0.25)" strokeWidth={4} />
    <path d="M -64 -30 C -78 -130 78 -130 64 -30 C 48 -86 -40 -86 -64 -30 Z" fill={pelo} />
    <circle cx={-22} cy={-26} r={6} fill="#1c1410" />
    <circle cx={22} cy={-26} r={6} fill="#1c1410" />
    <path d="M -16 8 Q 0 20 16 8" stroke="#8a3d2f" strokeWidth={5} fill="none" strokeLinecap="round" />
  </g>
);

// ---- Sitio 1: mesa, papel que se desenrolla por el pasillo (E1-E6) ----
const PAPEL: [number, number][] = [[540, 1760], [540, 1150], [610, 760], [520, 430], [560, 120]];
const Mesa: React.FC = () => {
  const {s, spr, lin} = useS();
  const D = lin(SU + 0.2, RADIO, 600, 1651);
  const pts = corta(PAPEL, D).map((p) => p.join(',')).join(' ');
  const tr = Array.from({length: 66}).map((_, k) => {
    const y = 1380 - k * 10;
    const td = s - (k * 10) / 90;
    const x = 540 + (h(Math.floor(td * 18) + 3) - 0.5) * 30 + 120 * Math.exp(-(((td - (HOMBRE + 0.05)) / 0.07) ** 2));
    return `${x.toFixed(1)},${y}`;
  }).join(' ');
  const paradas = [
    {t: 0, x: 540, y: 1330, zoom: 1.0},
    {t: HOMBRE, x: 540, y: 1250, zoom: 1.45},
    {t: JOC, x: 500, y: 1330, zoom: 1.4},
    {t: VEINTI + 0.5, x: 440, y: 1420, zoom: 1.05},
    {t: SU, x: 540, y: 1250, zoom: 1.0},
    {t: KM, x: 560, y: 900, zoom: 1.2},
    {t: RADIO, x: 540, y: 560, zoom: 1.2},
    {t: UN, x: 610, y: 780, zoom: 1.3},
    {t: MANCH, x: 610, y: 770, zoom: 2.2},
    {t: BROMA + 1.5, x: 620, y: 760, zoom: 1.85},
  ];
  const aliAp = spr(HOMBRE, 11, 130);
  const doodle = lin(JOC, JOC + 0.7, 0, 1);
  const ax = 540 + (330 - 540) * doodle, ay = 1070 + (1210 - 1070) * doodle, asc = 1 * (1 - 0.62 * doodle);
  const pulso = (i: number) => spr(CADA + 0.15 + i * 1.3, 9, 160);
  const bal = Math.sin(((s - CADA) / 1.3) * Math.PI * 2) * 28;
  const LG = interpolate(s, [NADA + 0.3, NADA + 1.6], [0, 5], clamp);
  return (
    <AbsoluteFill style={{background: 'linear-gradient(180deg, #0A1230, #12204A)'}}>
      <Camara paradas={paradas}>
        <Textura tipo="fibra" base="linear-gradient(180deg, #0A1230, #14234F 60%, #1B2C5E)" linea="rgba(120,150,230,0.25)" luz="rgba(160,190,255,0.14)" semilla={12} />
        <Lienzo>
          {Array.from({length: 11}).map((_, i) => <line key={i} x1={540} y1={-250} x2={-700 + i * 260} y2={1980} stroke="rgba(150,180,255,0.1)" strokeWidth={4} />)}
          <rect x={455} y={20} width={170} height={200} rx={10} fill="#091028" stroke="#D8C89A" strokeWidth={8} />
          <circle cx={595} cy={125} r={9} fill="#D8C89A" />
          <polyline points={PAPEL.map((p) => p.join(',')).join(' ')} fill="none" stroke="rgba(255,255,255,0.05)" strokeWidth={300} strokeLinejoin="round" strokeLinecap="round" />
          <polyline points={pts} fill="none" stroke="#B9A57A" strokeWidth={300} strokeLinejoin="round" strokeLinecap="round" />
          <polyline points={pts} fill="none" stroke={CREMA} strokeWidth={282} strokeLinejoin="round" strokeLinecap="round" />
          <polyline points={pts} fill="none" stroke="#B79F73" strokeWidth={282} strokeDasharray="3 37" opacity={0.45} strokeLinejoin="round" />
          <polyline points={tr} fill="none" stroke="#1d2a55" strokeWidth={5} strokeLinejoin="round" />
          {/* plumilla */}
          <g>
            <line x1={880} y1={1560} x2={548} y2={1386} stroke="#222" strokeWidth={22} strokeLinecap="round" />
            <path d="M 548 1386 L 530 1370 L 560 1374 Z" fill="#C9A227" />
          </g>
          {/* Jocelyn inclinada sobre el papel */}
          <g transform={`translate(${-420 * (1 - spr(JOC, 14, 90))} 0)`}>
            <Figura x={235} y={1500} sc={1.35} rot={22} pelo="#2a1c16" ropa="#2F5D62" />
            <line x1={330} y1={1520} x2={470} y2={1430} stroke="#2F5D62" strokeWidth={34} strokeLinecap="round" />
            <circle cx={478} cy={1424} r={20} fill="#E8B894" />
          </g>
          {/* trazo con el alien */}
          <g opacity={aliAp > 0.01 ? 1 : 0}><Alien x={ax} y={ay} sc={asc * aliAp} guino={s > HOMBRE + 0.5 && s < HOMBRE + 0.9 ? 1 : 0} /></g>
          {/* la manchita */}
          {s > UN && (
            <g transform="translate(610 760)">
              <circle r={70} fill={LIMA} opacity={0.18 * spr(MANCH, 10, 130)} />
              <path d="M -26 -8 C -30 -30 6 -34 24 -18 C 40 -4 30 22 6 26 C -18 30 -34 14 -26 -8 Z" fill={LIMA} stroke="#8a9a00" strokeWidth={3} transform={`scale(${spr(UN + 0.2, 9, 150)})`} />
              {s > MANCH && s < CADA - 0.3 && <circle r={interpolate(s, [MANCH, MANCH + 0.4], [150, 66], clamp)} fill="none" stroke={LIMA} strokeWidth={9} />}
            </g>
          )}
          {/* pulsos idénticos y separados */}
          {s > CADA && [0, 1, 2, 3].map((i) => {
            const k = pulso(i);
            if (k <= 0.01) return null;
            const p = 1 + 0.25 * Math.max(0, Math.sin(((s - CADA - 0.15 - i * 1.3) / 1.3) * Math.PI * 2));
            return <g key={i} transform={`translate(${520 + i * 84 - 0} 700)`}><circle r={30} fill="rgba(231,255,0,0.25)" transform={`scale(${k * p})`} /><circle r={17} fill={LIMA} stroke="#8a9a00" strokeWidth={3} transform={`scale(${k * p})`} /></g>;
          })}
          {/* metrónomo */}
          {s > CADA - 0.3 && (
            <g transform="translate(380 900)">
              <path d="M -50 90 L -22 -90 L 22 -90 L 50 90 Z" fill="#3A2A18" stroke="#D8C89A" strokeWidth={5} />
              <g transform={`rotate(${bal} 0 70)`}><line x1={0} y1={70} x2={0} y2={-130} stroke="#E8E8E8" strokeWidth={8} strokeLinecap="round" /><rect x={-14} y={-90} width={28} height={26} rx={5} fill={LIMA} /></g>
            </g>
          )}
          {/* lápiz: LGM-1 */}
          {s > NADA && <text x={460} y={600} fontFamily={MANO} fontSize={64} fill="#3a3a3a" transform="rotate(-6 460 600)">{'LGM-1'.slice(0, Math.ceil(LG))}</text>}
          {s > BROMA - 0.1 && <Alien x={800} y={620} sc={0.5 * spr(BROMA, 10, 140)} risa rot={golpe(s, BROMA, 18, 4) * 12} />}
        </Lienzo>
        <Brillo x={610} y={770} r={380} color="rgba(231,255,0,0.22)" t0={MANCH} />
        <Ondas x={610} y={760} t0={CADA + 0.15} color={LIMA} radio={160} />
        <Ondas x={610} y={760} t0={CADA + 1.45} color={LIMA} radio={160} />
        <Ondas x={610} y={760} t0={CADA + 2.75} color={LIMA} radio={160} />
      </Camara>
      <Chip texto="1967" x={540} y={520} t0={Y1967} t1={Y1967 + 2.6} color={LIMA} size={80} />
      <Chip texto="24 años" x={540} y={520} t0={VEINTI} t1={SU - 0.2} color={LIMA} size={80} />
      {s < UN - 0.2 && <Regla x={330} y={1000} largo={420} t0={KM} texto="Kilómetros" vertical={false} />}
      {s > CADA && s < RELOJ + 1.6 && <Contador desde={0} hasta={1.3} t0={CADA} t1={en('segundos') + 0.1} x={540} y={520} decimales={1} sufijo=" s" size={80} color={LIMA} />}
    </AbsoluteFill>
  );
};

// ---- Sitio 2: cielo nocturno sobre antenas (E7-E8) ----
const Cielo: React.FC = () => {
  const {s, spr, lin} = useS();
  const paradas = [
    {t: SEMANAS - 0.3, x: 360, y: 900, zoom: 1.3},
    {t: OTRA - 0.2, x: 360, y: 880, zoom: 1.3},
    {t: OTRA + 0.6, x: 760, y: 700, zoom: 1.3},
    {t: EXTRA - 0.2, x: 760, y: 700, zoom: 1.3},
    {t: NO2, x: 540, y: 960, zoom: 1.0},
  ];
  const pulse = (x: number, y: number, t0: number, k = 0) => {
    const a = spr(t0, 10, 130);
    const p = 1 + 0.3 * Math.max(0, Math.sin(((s - t0) / 1.3) * Math.PI * 2));
    return <g transform={`translate(${x} ${y}) scale(${a * p})`}><circle r={60} fill="rgba(231,255,0,0.2)" /><circle r={22} fill={LIMA} stroke="#8a9a00" strokeWidth={3} /></g>;
  };
  const X = lin(NO2, NO2 + 0.35, 0, 1);
  return (
    <AbsoluteFill style={{background: NOCHE}}>
      <Camara paradas={paradas}>
        <Textura tipo="papel" base="radial-gradient(circle at 50% 60%, #1D3170, #0E1A3A 65%, #050A1E)" linea="rgba(160,190,255,0.3)" luz="rgba(120,150,255,0.15)" semilla={14} />
        <Lienzo>
          {Array.from({length: 70}).map((_, i) => <circle key={i} cx={h(i) * 1080} cy={h(i * 3) * 1300} r={1.5 + h(i * 7) * 3.5} fill="#fff" opacity={0.35 + 0.4 * Math.abs(Math.sin(s * 1.5 + i))} />)}
          {[120, 420, 720, 960, 280].map((x, i) => (
            <g key={i} transform={`translate(${x} ${1790 - (i % 2) * 40}) rotate(${-25 + Math.sin(s * 0.4 + i) * 8})`}>
              <rect x={-8} y={-6} width={16} height={140} fill="#050A1E" transform="rotate(25)" />
              <path d="M -90 -20 Q 0 90 90 -20 Q 0 20 -90 -20 Z" fill="#0A1230" stroke="#5F7BC8" strokeWidth={5} />
              <line x1={0} y1={0} x2={0} y2={-70} stroke="#5F7BC8" strokeWidth={5} />
            </g>
          ))}
          <rect x={0} y={1780} width={1080} height={200} fill="#050A1E" />
          {pulse(360, 760, 0)}
          {s > OTRA && pulse(770, 520, OTRA)}
          {s > EXTRA - 0.1 && (
            <>
              <Alien x={360} y={740} sc={0.55 * spr(EXTRA, 10, 130)} risa={false} rot={-6} />
              <Alien x={770} y={500} sc={0.55 * spr(EXTRA + 0.15, 10, 130)} rot={6} />
              {[[360, 840, -1], [770, 600, 1]].map(([x, y, d], i) => (
                <g key={i} transform={`translate(${x} ${y}) rotate(${golpe(s, EXTRA + i * 0.2, 25, 3) * 14})`}>
                  <rect x={d * 70 - 18} y={-18} width={36} height={60} rx={7} fill="#222" stroke="#888" strokeWidth={3} />
                  <rect x={d * 70 - 13} y={-12} width={26} height={38} fill={LIMA} opacity={0.8} />
                </g>
              ))}
            </>
          )}
          {s > NO2 - 0.02 && (
            <g stroke={LIMA} strokeWidth={34} strokeLinecap="round" opacity={X}>
              <line x1={240} y1={420} x2={240 + 600 * X} y2={420 + 560 * X} />
              <line x1={840} y1={420} x2={840 - 600 * Math.max(0, X * 1.1 - 0.1)} y2={420 + 560 * Math.max(0, X * 1.1 - 0.1)} />
            </g>
          )}
        </Lienzo>
        <Brillo x={360} y={760} r={300} color="rgba(231,255,0,0.2)" />
      </Camara>
    </AbsoluteFill>
  );
};

// ---- Sitio 3: la estrella de neutrones (E9-E10) ----
const RECO: [number, number][] = [[540, 880], [470, 1180], [330, 1450]];
const Estrella: React.FC = () => {
  const {s, spr, lin} = useS();
  const ang = (s - ESTRELLA) * 150;
  const paradas = [
    {t: ESTRELLA, x: 480, y: 900, zoom: 1.25},
    {t: CIUDAD, x: 620, y: 960, zoom: 1.25},
    {t: HABIA - 0.2, x: 540, y: 960, zoom: 1.1},
    ...seguir(RECO, HABIA, PULSARES, 1.3, 4),
    {t: PULSARES + 1.2, x: 460, y: 1450, zoom: 1.3},
  ];
  const e = spr(ESTRELLA, 12, 100);
  const pasa = lin(HABIA, PULSARES - 0.2, 0, 1);
  return (
    <AbsoluteFill style={{background: '#040818'}}>
      <Camara paradas={paradas}>
        <Textura tipo="papel" base="radial-gradient(circle at 50% 45%, #1A2A66, #0B1236 60%, #02040E)" linea="rgba(160,190,255,0.3)" luz="rgba(120,160,255,0.12)" semilla={16} />
        <Lienzo>
          <defs>
            <radialGradient id="estG" cx="38%" cy="32%" r="75%"><stop offset="0%" stopColor="#E4ECFA" /><stop offset="45%" stopColor="#8FA2C8" /><stop offset="100%" stopColor="#2A3550" /></radialGradient>
            <linearGradient id="hazG" x1="0" y1="0" x2="1" y2="0"><stop offset="0%" stopColor="#F4FF9A" stopOpacity={0.95} /><stop offset="100%" stopColor={LIMA} stopOpacity={0} /></linearGradient>
          </defs>
          {Array.from({length: 60}).map((_, i) => <circle key={i} cx={h(i + 5) * 1080} cy={h(i * 3 + 1) * 1920} r={1.5 + h(i * 7) * 2.5} fill="#fff" opacity={0.5} />)}
          <g transform={`translate(540 880) rotate(${ang})`} opacity={e}>
            <polygon points="0,-60 1500,-170 1500,170 0,60" fill="url(#hazG)" opacity={0.8} />
            <polygon points="0,-60 -1500,-170 -1500,170 0,60" fill="url(#hazG)" opacity={0.8} transform="scale(-1 -1)" />
          </g>
          {[0, 1, 2].map((i) => <ellipse key={i} cx={540} cy={880} rx={250 + i * 60} ry={110 + i * 40} fill="none" stroke="rgba(150,190,255,0.4)" strokeWidth={4} transform={`rotate(${ang * 0.3 + i * 40} 540 880)`} />)}
          <circle cx={540} cy={880} r={190 * e} fill="rgba(160,190,255,0.25)" />
          <circle cx={540} cy={880} r={170 * e} fill="url(#estG)" stroke="#16203C" strokeWidth={6} />
          <ellipse cx={490} cy={820} rx={36} ry={22} fill="#fff" opacity={0.45} />
          {/* ciudad a escala */}
          {s > CIUDAD - 0.5 && (
            <g opacity={spr(CIUDAD - 0.4, 12, 120)}>
              <line x1={370} y1={880} x2={370} y2={1440} stroke={LIMA} strokeWidth={3} strokeDasharray="10 12" opacity={0.7} />
              <line x1={710} y1={880} x2={710} y2={1440} stroke={LIMA} strokeWidth={3} strokeDasharray="10 12" opacity={0.7} />
              {Array.from({length: 9}).map((_, i) => {
                const hh = 60 + h(i * 3) * 150;
                return <g key={i}><rect x={370 + i * 38} y={1440 - hh} width={34} height={hh} fill="#0A1030" stroke="#7F9AE0" strokeWidth={3} />{Array.from({length: 3}).map((_, k) => <rect key={k} x={378 + i * 38} y={1450 - hh + k * 40} width={8} height={10} fill="#FFE98A" />)}</g>;
              })}
              <line x1={340} y1={1440} x2={740} y2={1440} stroke="#7F9AE0" strokeWidth={5} />
            </g>
          )}
          {/* la Tierra y el papel */}
          <circle cx={330} cy={1560} r={130} fill="#2D6FD0" stroke="#10306A" strokeWidth={6} />
          <path d="M 250 1520 C 290 1490 330 1530 320 1570 C 300 1610 250 1600 250 1560 Z M 350 1600 C 390 1580 410 1620 390 1650 C 360 1660 340 1630 350 1600 Z" fill="#4FB070" />
          {s > PULSARES - 0.3 && (
            <g opacity={spr(PULSARES - 0.2, 12, 120)}>
              <rect x={600} y={1470} width={330} height={150} fill={CREMA} stroke="#B79F73" strokeWidth={5} />
              <polyline points={`610,1560 680,1556 720,1562 770,1480 800,1590 850,1560 920,1558`} fill="none" stroke="#1d2a55" strokeWidth={5} />
              <circle cx={770} cy={1480} r={11} fill={LIMA} />
            </g>
          )}
          <Recorrido puntos={RECO} t0={HABIA} t1={PULSARES - 0.15} color="rgba(231,255,0,0.9)" render={(x, y) => <circle cx={x} cy={y} r={20} fill={LIMA} stroke="#8a9a00" strokeWidth={3} />} />
        </Lienzo>
        <Brillo x={540} y={880} r={420} color="rgba(150,180,255,0.35)" />
        {s > HABIA && pasa < 1 && <Brillo x={330} y={1560} r={260} color={`rgba(231,255,0,${0.4 * pasa})`} />}
      </Camara>
      <Chip texto="Púlsar" x={540} y={520} t0={PULSARES} t1={PULSARES + 2.2} color={LIMA} size={84} />
    </AbsoluteFill>
  );
};

// ---- Sitio 4: salón de premios (E11-E13) ----
const Salon: React.FC = () => {
  const {s, spr, lin} = useS();
  const medalla = lin(DIERON - 0.1, DIERON + 0.9, 0, 1, Easing.inOut(Easing.cubic));
  const mx = 540 + (760 - 540) * medalla, my = 640 + (1330 - 640) * medalla;
  const calida = interpolate(s, [CUARENTA - 0.3, CUARENTA + 0.6], [0, 1], clamp);
  const pelo = tono(s, [0, CUARENTA], ['#2a1c16', '#BDBDBD'], 0.8);
  const paradas = [
    {t: Y1974, x: 540, y: 960, zoom: 1.0},
    {t: ELLA - 0.4, x: 540, y: 960, zoom: 1.0},
    {t: ELLA + 0.6, x: 300, y: 1200, zoom: 1.35},
    {t: CUARENTA - 0.2, x: 300, y: 1050, zoom: 1.3},
    {t: PREMIO2, x: 440, y: 900, zoom: 1.1},
    {t: DONO, x: 540, y: 900, zoom: 1.15},
    {t: ESTUD + 0.2, x: 540, y: 960, zoom: 1.0},
  ];
  const flap = lin(DONO, DONO + 0.5, 0, 1);
  const estudiantes = [140, 340, 540, 740, 940];
  return (
    <AbsoluteFill style={{background: '#070B1C'}}>
