        <Lienzo>
          <defs>
            <radialGradient id="oroG" cx="35%" cy="30%" r="75%"><stop offset="0%" stopColor="#FFF3B8" /><stop offset="55%" stopColor="#D5BC62" /><stop offset="100%" stopColor="#8A7326" /></radialGradient>
          </defs>
          <polygon points="540,0 240,1400 840,1400" fill="rgba(200,215,255,0.07)" />
          <rect x={0} y={1400} width={1080} height={520} fill="#0B1230" />
          <line x1={0} y1={1400} x2={1080} y2={1400} stroke="#3F4F8A" strokeWidth={6} />
