          <Figura x={760} y={1190} sc={1.4} pelo="#C9C9C9" ropa="#26262E" corbata="#8E1B2E" />
          <g transform={`translate(${mx} ${my}) scale(${spr(NOBEL - 1.2, 11, 120)}) rotate(${Math.sin(s * 3) * 4})`}>
            <path d="M -40 -150 L 0 -60 L 40 -150 L 60 -150 L 0 -20 L -60 -150 Z" fill="#9E2236" />
            <circle r={72} fill="url(#oroG)" stroke="#6E5A18" strokeWidth={6} />
