            <text y={14} textAnchor="middle" fontFamily={FONT} fontWeight={800} fontSize={44} fill="#6E5A18">N</text>
          </g>
          {/* sobre */}
          {s > PREMIO2 - 0.4 && (
            <g transform={`translate(540 1000) scale(${spr(PREMIO2 - 0.3, 11, 120)})`}>
              <rect x={-170} y={-110} width={340} height={220} rx={12} fill="#F3EAD0" stroke="#A89560" strokeWidth={6} />
