              <circle cx={0} cy={0} r={30} fill={LIMA} opacity={0.85} />
            </g>
          )}
          {/* hojas que caen sobre los jóvenes */}
          {s > DONO && Array.from({length: 14}).map((_, i) => {
            const t = s - DONO - i * 0.1;
            if (t < 0) return null;
            const k = Math.min(1, t / 1.3);
            const tx = estudiantes[i % 5];
            return <rect key={i} x={540 + (tx - 540) * k - 34} y={1000 + (1360 - 1000) * k * k - 24} width={68} height={48} fill="#fff" stroke="#B79F73" strokeWidth={3} transform={`rotate(${k * 200 * (i % 2 ? 1 : -1)} ${540 + (tx - 540) * k} ${1000 + 360 * k * k})`} opacity={1 - Math.max(0, (t - 1.3) / 0.5)} />;
