    </AbsoluteFill>
  );
};

// ---- Sitio 5: vuelve el papel y la manchita (E14-E15) ----
const MesaFin: React.FC = () => {
  const {s, spr, lin} = useS();
  const tr = Array.from({length: 66}).map((_, k) => {
    const y = 1500 - k * 14;
    const td = s - (k * 14) / 90;
    const x = 540 + (h(Math.floor(td * 18) + 3) - 0.5) * 30 + 140 * Math.exp(-(Math.pow(((td - MANCH2) % 1.3 + 1.3) % 1.3 - 0.2, 2) / 0.0049));
    return `${x.toFixed(1)},${y}`;
  }).join(' ');
  const p = 1 + 0.18 * Math.max(0, Math.sin(((s - MANCH2) / 1.3) * Math.PI * 2));
  const paradas = [{t: MANCH2 - 0.5, x: 540, y: 1000, zoom: 1.0}, {t: MANCH2 + 2.4, x: 560, y: 940, zoom: 1.35}];
  return (
    <AbsoluteFill style={{background: '#8d7a52'}}>
      <Camara paradas={paradas}>
        <Textura tipo="papel" base="radial-gradient(circle at 50% 40%, #F6EDD6, #D9C9A0 70%, #8d7a52)" linea="rgba(120,90,50,0.35)" luz="rgba(255,250,230,0.3)" semilla={20} />
        <Lienzo>
          <rect x={390} y={-100} width={300} height={2200} fill={CREMA} stroke="#B79F73" strokeWidth={6} />
          <rect x={390} y={-100} width={300} height={2200} fill="none" stroke="#B79F73" strokeWidth={300} strokeDasharray="3 37" opacity={0.25} />
          <polyline points={tr} fill="none" stroke="#1d2a55" strokeWidth={6} strokeLinejoin="round" />
          {/* hojas que se juntan en el rollo (llegan desde el salón) */}
          {Array.from({length: 10}).map((_, i) => {
            const k = lin(MANCH2 - 0.4, MANCH2 + 0.9, 0, 1, Easing.out(Easing.cubic));
            if (k >= 1) return null;
            const ox = h(i * 3) * 1000, oy = h(i * 5) * 1700;
            return <rect key={i} x={ox + (540 - ox) * k - 34} y={oy + (1000 - oy) * k - 24} width={68} height={48} fill="#fff" stroke="#B79F73" strokeWidth={3} transform={`rotate(${k * 160} ${540} ${1000})`} opacity={1 - k} />;
          })}
          <g transform="translate(540 1000)">
            <circle r={150 * p} fill="rgba(231,255,0,0.22)" />
            <path d="M -50 -14 C -58 -58 12 -66 48 -34 C 80 -8 58 44 12 52 C -36 60 -68 28 -50 -14 Z" fill={LIMA} stroke="#8a9a00" strokeWidth={5} transform={`scale(${p})`} />
            <ellipse cx={-14} cy={-26} rx={12} ry={7} fill="#fff" opacity={0.6} />
          </g>
          {/* medalla con su nombre */}
          {s > LLEVA - 0.1 && (
            <g transform={`translate(780 1130) scale(${spr(LLEVA, 11, 130)})`}>
              <path d="M -26 -80 L 0 -30 L 26 -80 L 40 -80 L 0 -10 L -40 -80 Z" fill="#9E2236" />
              <circle r={62} fill="url(#oroG2)" stroke="#6E5A18" strokeWidth={5} />
              <text y={8} textAnchor="middle" fontFamily={FONT} fontWeight={800} fontSize={25} fill="#4A3C0E">Jocelyn</text>
              <defs><radialGradient id="oroG2" cx="35%" cy="30%" r="75%"><stop offset="0%" stopColor="#FFF3B8" /><stop offset="55%" stopColor="#D5BC62" /><stop offset="100%" stopColor="#8A7326" /></radialGradient></defs>
            </g>
          )}
        </Lienzo>
        <Ondas x={540} y={1000} t0={MANCH2 + 0.2} color="#8a9a00" radio={260} />
        <Ondas x={540} y={1000} t0={MANCH2 + 1.5} color="#8a9a00" radio={260} />
        <Ondas x={540} y={1000} t0={MANCH2 + 2.8} color="#8a9a00" radio={260} />
        <Ondas x={540} y={1000} t0={MANCH2 + 4.1} color="#8a9a00" radio={260} />
      </Camara>
    </AbsoluteFill>
  );
};

